//! Local fixtures only (tests/fixtures, regenerated by gen.py). No network.
#![allow(clippy::unwrap_used)]
use logo::*;

const MARK: &[u8] = b"CENTURION_EXIF_MARKER_7f3a";

fn fx(name: &str) -> Vec<u8> {
    std::fs::read(format!(
        "{}/tests/fixtures/{name}",
        env!("CARGO_MANIFEST_DIR")
    ))
    .expect("fixture")
}

fn contains(h: &[u8], n: &[u8]) -> bool {
    h.windows(n.len()).any(|w| w == n)
}

fn px_of(outs: &[Output], size: u32) -> Vec<u8> {
    decode(
        &outs
            .iter()
            .find(|o| o.size == size && o.format == OutFormat::Webp)
            .expect("size")
            .bytes,
    )
    .expect("our webp decodes")
    .data
}

#[test]
fn sniff_accepts_only_raster_magic() {
    assert_eq!(sniff(&fx("photo_exif.jpg")), Ok(Format::Jpeg));
    assert_eq!(sniff(&fx("alpha_text.png")), Ok(Format::Png));
    assert_eq!(sniff(&fx("anim.gif")), Ok(Format::Gif));
    assert_eq!(sniff(&fx("anim.webp")), Ok(Format::Webp));
    assert_eq!(sniff(b""), Err(LogoError::Empty));
    assert_eq!(sniff(&fx("not_image.html")), Err(LogoError::Unsupported));
    assert_eq!(sniff(b"BM\x00\x00\x00\x00"), Err(LogoError::Unsupported)); // BMP not allowed
}

#[test]
fn svg_is_rejected_never_passed_through() {
    for f in ["logo.svg", "svg_no_decl.svg"] {
        let e = transcode_all(&fx(f)).err().expect("rejected");
        assert_eq!(e, LogoError::SvgRejected, "{f}");
        assert!(e.is_rejection());
    }
    // SVG behind a PNG signature is not a valid PNG either
    let mut fake = b"\x89PNG\r\n\x1a\n".to_vec();
    fake.extend_from_slice(&fx("logo.svg"));
    assert!(matches!(transcode_all(&fake), Err(LogoError::Decode(_))));
}

#[test]
fn oversize_input_rejected() {
    let mut big = fx("alpha_text.png");
    big.resize(MAX_INPUT + 1, 0);
    assert_eq!(decode(&big).err(), Some(LogoError::TooLargeInput));
}

#[test]
fn decompression_bombs_rejected_before_allocation() {
    let e = decode(&fx("bomb_30000.png")).err().expect("bomb");
    assert_eq!(
        e,
        LogoError::TooLargeDimensions {
            width: 30000,
            height: 30000
        }
    );
    let e = decode(&fx("bomb_screen.gif")).err().expect("gif bomb");
    assert_eq!(
        e,
        LogoError::TooLargeDimensions {
            width: 65535,
            height: 65535
        }
    );
    // JPEG: patch the SOF0 frame size to 60000x60000
    let mut j = fx("photo_exif.jpg");
    let i = j.windows(2).position(|w| w == [0xFF, 0xC0]).expect("SOF0");
    j[i + 5..i + 7].copy_from_slice(&60000u16.to_be_bytes());
    j[i + 7..i + 9].copy_from_slice(&60000u16.to_be_bytes());
    assert!(
        matches!(decode(&j), Err(LogoError::TooLargeDimensions { .. })),
        "{:?}",
        decode(&j).err()
    );
    // 5000 x 1 passes the pixel cap but not the side cap
    let mut v = Vec::new();
    {
        let mut e = png::Encoder::new(&mut v, 5000, 1);
        e.set_color(png::ColorType::Grayscale);
        let mut w = e.write_header().unwrap();
        w.write_image_data(&vec![0u8; 5000]).unwrap();
        w.finish().unwrap();
    }
    assert_eq!(
        decode(&v).err(),
        Some(LogoError::TooLargeDimensions {
            width: 5000,
            height: 1
        })
    );
}

#[test]
fn metadata_is_stripped() {
    for f in ["photo_exif.jpg", "alpha_text.png", "still.webp"] {
        let input = fx(f);
        assert!(contains(&input, MARK), "fixture {f} must carry the marker");
        for o in transcode_all(&input).expect(f) {
            assert!(
                !contains(&o.bytes, MARK),
                "{f} -> {} leaked metadata",
                o.file_name()
            );
            assert!(!contains(&o.bytes, b"Exif") && !contains(&o.bytes, b"CenturionCam"));
            assert!(
                !contains(&o.bytes, b"EXIF")
                    && !contains(&o.bytes, b"XMP ")
                    && !contains(&o.bytes, b"ICCP")
            );
            assert!(
                !contains(&o.bytes, b"ANIM") && !contains(&o.bytes, b"VP8X"),
                "simple container only"
            );
        }
    }
}

#[test]
fn resize_outputs_all_sizes_webp_and_png_within_budget() {
    let outs = transcode_all(&fx("photo_exif.jpg")).expect("jpeg");
    let names: Vec<String> = outs.iter().map(|o| o.file_name()).collect();
    assert_eq!(
        names,
        [
            "48.webp", "64.webp", "96.webp", "128.webp", "192.webp", "48.png", "64.png", "96.png",
            "128.png", "192.png"
        ]
    );
    for o in &outs {
        let d = decode(&o.bytes).expect("re-decodes");
        assert_eq!((d.width, d.height), (o.size, o.size));
        let want = if o.format == OutFormat::Webp {
            Format::Webp
        } else {
            Format::Png
        };
        assert_eq!(sniff(&o.bytes), Ok(want));
        assert!(
            o.bytes.len() <= HARD_MAX_BYTES,
            "{} is {} bytes",
            o.file_name(),
            o.bytes.len()
        );
        if o.size <= 96 && o.format == OutFormat::Webp {
            assert!(
                o.bytes.len() <= TARGET_BYTES,
                "{} is {} bytes",
                o.file_name(),
                o.bytes.len()
            );
        }
    }
    // PNG carries only IHDR/IDAT/IEND
    for o in outs.iter().filter(|o| o.format == OutFormat::Png) {
        for c in [
            &b"tEXt"[..],
            b"zTXt",
            b"iTXt",
            b"eXIf",
            b"iCCP",
            b"tIME",
            b"gAMA",
            b"acTL",
        ] {
            assert!(
                !contains(&o.bytes, c),
                "{} has {:?}",
                o.file_name(),
                std::str::from_utf8(c)
            );
        }
    }
    // 300x200 -> 96: content 96x64 centered on transparency; left red, right blue
    assert_eq!(outs[2].bits, 8, "simple image needs no posterization");
    assert_eq!((outs[2].size, outs[2].format), (96, OutFormat::Webp));
    let px = px_of(&outs, 96);
    let at = |x: usize, y: usize| px[(y * 96 + x) * 4..(y * 96 + x) * 4 + 4].to_vec();
    assert_eq!(at(48, 0)[3], 0, "top letterbox transparent");
    assert_eq!(at(48, 95)[3], 0, "bottom letterbox transparent");
    let (l, r) = (at(15, 48), at(80, 48));
    assert!(l[0] > 180 && l[2] < 80 && l[3] == 255, "left red {l:?}");
    assert!(r[2] > 180 && r[0] < 80 && r[3] == 255, "right blue {r:?}");
}

#[test]
fn byte_budget_posterizes_noisy_images() {
    let mut x: u32 = 0x1234_5678; // deterministic noise: incompressible at 8 bits/channel
    let mut px = Vec::with_capacity(96 * 96 * 4);
    for _ in 0..96 * 96 {
        for _ in 0..3 {
            x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            px.push((x >> 24) as u8);
        }
        px.push(255);
    }
    assert!(
        encode_webp(&px, 96).unwrap().len() > HARD_MAX_BYTES,
        "noise is big unposterized"
    );
    match encode_webp_budget(&px, 96) {
        Ok((b, bits)) => {
            assert!(
                bits < 8 && b.len() <= HARD_MAX_BYTES,
                "bits {bits} len {}",
                b.len()
            );
            assert!(
                decode(&b).unwrap().data.chunks(4).all(|p| p[3] == 255),
                "alpha kept exact"
            );
        }
        Err(e) => assert_eq!(e, LogoError::OutputTooLarge),
    }
    // full transparency and opacity survive posterization
    let (b, _) = encode_webp_budget(&[0, 0, 0, 0, 255, 255, 255, 255].repeat(48 * 96), 96).unwrap();
    assert_eq!(
        &decode(&b).unwrap().data[0..8],
        &[0, 0, 0, 0, 255, 255, 255, 255]
    );
}

#[test]
fn alpha_and_gray_and_upscale() {
    // 64x64 with a 32x32 opaque green centre -> 48 px: centre opaque, corners transparent, no dark halo
    let px = px_of(&transcode_all(&fx("alpha_text.png")).unwrap(), 48);
    let at = |x: usize, y: usize| px[(y * 48 + x) * 4..(y * 48 + x) * 4 + 4].to_vec();
    assert_eq!(at(0, 0)[3], 0);
    assert_eq!(at(24, 24), vec![10, 200, 10, 255]);
    // grayscale 10x40 -> pillarboxed
    let px = px_of(&transcode_all(&fx("gray_tall.png")).unwrap(), 96);
    assert_eq!(px[(48 * 96) * 4 + 3], 0, "left pillarbox transparent");
    assert_eq!(
        &px[(48 * 96 + 48) * 4..(48 * 96 + 48) * 4 + 4],
        &[128, 128, 128, 255]
    );
}

#[test]
fn animated_inputs_use_first_frame_only() {
    for f in ["anim.gif", "anim.webp"] {
        for o in transcode_all(&fx(f)).expect(f) {
            let d = decode(&o.bytes).unwrap();
            let c = &d.data
                [(d.width as usize * (d.height as usize / 2) + d.width as usize / 2) * 4..][..4];
            assert!(
                c[0] > 200 && c[2] < 50,
                "{f}: first frame (red) expected, got {c:?}"
            );
        }
    }
}

#[test]
fn truncated_and_garbage_fail_cleanly() {
    let j = fx("photo_exif.jpg");
    assert!(transcode_all(&j[..40]).is_err());
    let p = fx("alpha_text.png");
    assert!(transcode_all(&p[..30]).is_err());
    let mut riff = b"RIFF\x10\x00\x00\x00WEBPVP8X".to_vec();
    riff.extend_from_slice(&[0xff; 20]);
    assert!(transcode_all(&riff).is_err());
}

#[test]
fn oversized_large_sizes_are_omitted_not_fatal() {
    // deterministic noise photo 256x256: the small WebP fits (posterized), big sizes may be dropped
    let mut x: u32 = 0x0bad_f00d;
    let mut px = Vec::with_capacity(256 * 256 * 4);
    for _ in 0..256 * 256 {
        for _ in 0..3 {
            x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            px.push((x >> 24) as u8);
        }
        px.push(255);
    }
    let input = encode_png(&px, 256).unwrap();
    match transcode_all(&input) {
        Ok(outs) => {
            assert!(outs
                .iter()
                .any(|o| o.size == 48 && o.format == OutFormat::Webp));
            for o in &outs {
                assert!(o.bytes.len() <= HARD_MAX_BYTES);
            }
            // within a format, sizes are a prefix of SIZES (no holes)
            for f in [OutFormat::Webp, OutFormat::Png] {
                let s: Vec<u32> = outs
                    .iter()
                    .filter(|o| o.format == f)
                    .map(|o| o.size)
                    .collect();
                assert_eq!(s[..], SIZES[..s.len()]);
            }
        }
        Err(e) => assert_eq!(e, LogoError::OutputTooLarge),
    }
}
